// Chapters 5 + 9 — allow-list and command parsing.
const ALLOWED = [111111111]; // <-- your Telegram user ID
const msg = $input.first().json.message || {};
const fromId = msg.from?.id;
const chatId = msg.chat?.id;
const text = (msg.text || '').trim();

if (!fromId || !chatId) return [];
if (!ALLOWED.includes(fromId)) {
  return [{ json: { denied: true, chatId, reply: '🚫 This bot is private.' } }];
}
if (!text.toLowerCase().startsWith('/draft')) {
  return [{ json: { denied: true, chatId, reply: 'Send /draft <content request> to create a draft.' } }];
}

const request = text.replace(/^\/draft\s*/i, '').trim();
const platform = /linkedin/i.test(request) ? 'LinkedIn'
  : /youtube|shorts/i.test(request) ? 'YouTube'
  : /email|newsletter/i.test(request) ? 'Email'
  : /instagram|reel|caption/i.test(request) ? 'Instagram'
  : 'General';

return [{ json: { allowed: true, chatId, request, platform } }];

// Chapter 5 quality gate + Chapter 9 approval gate.
const raw = ($input.first().json?.message?.content || '').trim();
const ctx = $('Allow-list & parse').first().json;
const draftText = raw || '[empty response — needs review]';

const issues = [];
let decision = 'approve';
if (draftText.length < 80) { issues.push('Draft is very short — hook, message or CTA may be missing.'); decision = 'revise'; }
if (/\b(guarantee|guaranteed|100%|instantly)\b/i.test(draftText)) { issues.push('Absolute/guaranteed claim — soften it.'); decision = 'revise'; }
if (/\d+\s?%/.test(draftText)) { issues.push('Percentage found — verify the source.'); decision = 'revise'; }
if (!/(reply|comment|save this|subscribe|dm|book a call|call to action)/i.test(draftText)) { issues.push('No clear call to action.'); decision = 'revise'; }

const stamp = new Date().toISOString();
const draftId = 'D-' + stamp.replace(/[-:T.Z]/g, '').slice(2, 12);

return [{
  json: {
    'Draft ID': draftId,
    'Task ID': '',
    Platform: ctx.platform,
    Draft: draftText,
    Status: 'Awaiting approval',
    Reviewer: '',
    'Decision At': '',
    Feedback: '',
    qaDecision: decision,
    qaIssues: issues.join('; '),
    chatId: ctx.chatId,
  },
}];

